    $('#setupForm', v).addEventListener('submit', async (e) => { e.preventDefault(); const f = e.target; if (f.password.value !== f.password2.value) { toast('비밀번호 확인이 일치하지 않습니다.', 'error'); return; } const d = WB.formData(f); delete d.password2; const btn = $('button[type=submit]', f); btn.disabled = true; try { const r = await api('POST', 'api/setup', d); S.token = r.token; store.set('wb_token', r.token); toast('설정이 완료되었습니다. 환영합니다!', 'success'); await boot(); } catch (x) { btn.disabled = false; } });
