    if ($('#gsTest', box)) $('#gsTest', box).addEventListener('click', async (e) => { const b = e.currentTarget; if (b.disabled) return; b.disabled = true; out.innerHTML = '<div class="help">연결을 확인하는 중…</div>'; try { const r = await api('POST', 'api/sites/' + sid + '/gsheets/test', body(), { silent: true }); out.innerHTML = stepsHtml(r); } catch (x) { out.innerHTML = x.data && x.data.steps ? stepsHtml(x.data) : '<div class="alert alert--error"><span>' + esc(x.message || '') + '</span></div>'; } finally { b.disabled = false; } });
    if ($('#gsSave', box)) $('#gsSave', box).addEventListener('click', async (e) => { const b = e.currentTarget; if (b.disabled) return; b.disabled = true; try { await api('PUT', 'api/sites/' + sid + '/gsheets', body()); toast('Google Sheets 연동 설정을 저장했습니다.', 'success'); await intgRender(box, sid, opts); } catch (x) { b.disabled = false; } });
